WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    ?sensor a sosa:Sensor ;
            schema:name "Bangs" .
    ?obs a sosa:Observation ;
         sosa:madeBySensor ?sensor ;
         sosa:observedProperty hyobs:AirTemperature2mMin ;
         sosa:hasSimpleResult ?temp ;
         sosa:resultTime ?date .
    FILTER(?temp < 0)
    FILTER(?date >= "2010-01-01"^^xsd:date && ?date <= "2020-12-31"^^xsd:date)
  }
}
